mod verify_tests {
    use biome_analyze::{AnalysisFilter, ControlFlow, Never, RuleFilter};
    use biome_js_parser::JsParserOptions;
    use biome_js_syntax::JsFileSource;
    use std::slice;

    fn count(code: &str) -> usize {
        let parsed = biome_js_parser::parse(code, JsFileSource::tsx(), JsParserOptions::default());
        let root = parsed.tree();
        let rule = RuleFilter::Rule("nursery", "noYodaExpression");
        let filter = AnalysisFilter {
            enabled_rules: Some(slice::from_ref(&rule)),
            ..AnalysisFilter::default()
        };
        let options = Default::default();
        let mut n = 0usize;
        crate::analyze(&root, filter, &options, JsFileSource::tsx(), None, |signal| {
            if signal.diagnostic().is_some() {
                n += 1;
            }
            ControlFlow::<Never>::Continue(())
        });
        n
    }

    #[test]
    fn verify_yoda() {
        assert!(
            crate::metadata()
                .find_rule("nursery", "noYodaExpression")
                .is_some(),
            "rule not registered"
        );
        assert_eq!(count("if (\"red\" == value) {}"), 1, "should flag string yoda");
        assert_eq!(count("if (5 != value) {}"), 1, "should flag numeric yoda");
        assert_eq!(count("if (value === \"red\") {}"), 0, "conventional order ok");
        assert_eq!(count("if (0 < value && value < 1) {}"), 0, "range check excluded");
        assert_eq!(count("if (1 < 2) {}"), 0, "both literals excluded");
    }
